import * as React from "react";

export type RadioIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function RadioIcon({ size = 20, ...props }: RadioIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="9" width="16" height="10" rx="1.5" /><circle cx="9" cy="14" r="2.5" /><path d="M14.5 12.5h3M14.5 15.5h3M7 9l5-5" />
    </svg>
  );
}
